using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// A four-sided piece cut from a surface. Corners are stored in order around the panel.
    /// </summary>
    public sealed class FacadePanel
    {
        public FacadePanel(Point3d[] corners, int index)
        {
            if (corners == null || corners.Length != 4)
                throw new ArgumentException("A facade panel needs exactly four corners.", nameof(corners));

            Corners = (Point3d[])corners.Clone();
            Index = index;

            Outline = new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });
            Center = new Point3d(
                (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4.0,
                (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4.0,
                (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4.0);

            // Edge k runs from corner k to corner k+1.
            EdgeLengths = new double[4];
            for (int k = 0; k < 4; k++)
                EdgeLengths[k] = Corners[k].DistanceTo(Corners[(k + 1) % 4]);

            DiagonalLengths = new[]
            {
                Corners[0].DistanceTo(Corners[2]),
                Corners[1].DistanceTo(Corners[3]),
            };

            Area = ComputeArea();
            Deviation = ComputeDeviation();
            Signature = BuildSignature();
        }

        /// <summary>The four corners, in order around the panel.</summary>
        public Point3d[] Corners { get; }

        /// <summary>Closed polyline through the four corners.</summary>
        public PolylineCurve Outline { get; }

        /// <summary>Area of the two triangles that split the quad along the first diagonal.</summary>
        public double Area { get; }

        public Point3d Center { get; }

        /// <summary>Position of the panel in the grid it was cut from.</summary>
        public int Index { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three corners.</summary>
        public double Deviation { get; }

        /// <summary>Edge lengths, in corner order: 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths { get; }

        /// <summary>Diagonal lengths: 0-2, 1-3.</summary>
        public double[] DiagonalLengths { get; }

        /// <summary>
        /// Width of the rectangle used for nesting: mean of the first and third edge lengths.
        /// </summary>
        public double RectWidth => (EdgeLengths[0] + EdgeLengths[2]) / 2.0;

        /// <summary>
        /// Height of the rectangle used for nesting: mean of the second and fourth edge lengths.
        /// </summary>
        public double RectHeight => (EdgeLengths[1] + EdgeLengths[3]) / 2.0;

        /// <summary>
        /// Sorted edge lengths followed by sorted diagonal lengths. Used to compare panels for identity.
        /// </summary>
        public double[] Signature { get; }

        private double ComputeArea()
        {
            Vector3d a = Corners[1] - Corners[0];
            Vector3d b = Corners[2] - Corners[0];
            Vector3d c = Corners[3] - Corners[0];
            return 0.5 * Vector3d.CrossProduct(a, b).Length + 0.5 * Vector3d.CrossProduct(b, c).Length;
        }

        private double ComputeDeviation()
        {
            Vector3d ab = Corners[1] - Corners[0];
            Vector3d ac = Corners[2] - Corners[0];
            Vector3d normal = Vector3d.CrossProduct(ab, ac);
            if (normal.Length < 1e-12)
                return double.PositiveInfinity; // first three corners are collinear: no plane to measure against

            normal.Unitize();
            Vector3d d = Corners[3] - Corners[0];
            return Math.Abs(normal.X * d.X + normal.Y * d.Y + normal.Z * d.Z);
        }

        private double[] BuildSignature()
        {
            var sig = new double[6];
            double[] edges = (double[])EdgeLengths.Clone();
            double[] diagonals = (double[])DiagonalLengths.Clone();
            Array.Sort(edges);
            Array.Sort(diagonals);
            Array.Copy(edges, 0, sig, 0, 4);
            Array.Copy(diagonals, 0, sig, 4, 2);
            return sig;
        }
    }
}

