using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;

namespace BenchPlugin.Facade
{
    /// <summary>Wraps a <see cref="FacadePanel"/> so it can travel on a Grasshopper wire.</summary>
    public class FacadePanelGoo : GH_Goo<FacadePanel>
    {
        public FacadePanelGoo()
        {
        }

        public FacadePanelGoo(FacadePanel panel)
            : base(panel)
        {
        }

        public override bool IsValid => Value != null;

        public override string TypeName => "Panel";

        public override string TypeDescription => "Facade panel: four corners, outline, area and planarity";

        public override IGH_Goo Duplicate() => new FacadePanelGoo(Value);

        public override string ToString() => Value == null ? "Null Panel" : $"Panel {Value.Index}";
    }

    /// <summary>Helpers for reading lists of panels from component inputs.</summary>
    public static class PanelInput
    {
        public static List<FacadePanel> ReadList(IGH_DataAccess DA, int index)
        {
            var goos = new List<FacadePanelGoo>();
            DA.GetDataList(index, goos);
            return goos.Where(g => g?.Value != null).Select(g => g.Value).ToList();
        }
    }
}

