using System.Collections.Generic;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>Cuts a surface into a regular grid of panels.</summary>
    public static class SurfacePanelizer
    {
        /// <summary>
        /// Divides the surface domain evenly into uCount x vCount cells. Each panel's corners are the
        /// surface points at its cell's corners. Panels are returned row by row (V outer, U inner), so
        /// panel index = vIndex * uCount + uIndex.
        /// </summary>
        public static List<FacadePanel> Panelize(Surface surface, int uCount, int vCount)
        {
            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            // Grid of surface points, (uCount + 1) x (vCount + 1), so each shared vertex is evaluated once.
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
            {
                double u = du.Min + du.Length * i / uCount;
                for (int j = 0; j <= vCount; j++)
                {
                    double v = dv.Min + dv.Length * j / vCount;
                    grid[i, j] = surface.PointAt(u, v);
                }
            }

            var panels = new List<FacadePanel>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    var corners = new[]
                    {
                        grid[i, j],
                        grid[i + 1, j],
                        grid[i + 1, j + 1],
                        grid[i, j + 1],
                    };
                    panels.Add(new FacadePanel(corners, j * uCount + i));
                }
            }
            return panels;
        }
    }
}

