namespace BenchPlugin.Facade
{
    public enum PanelKind
    {
        Flat,
        ColdBent,
        Custom,
    }

    /// <summary>Sorts a panel into flat / cold-bent / custom by its planarity deviation.</summary>
    public static class PanelClassifier
    {
        /// <summary>Cold-bent panels may deviate up to this many times the tolerance.</summary>
        public const double ColdBentFactor = 10.0;

        public static PanelKind Classify(double deviation, double tolerance)
        {
            if (deviation <= tolerance) return PanelKind.Flat;
            if (deviation <= ColdBentFactor * tolerance) return PanelKind.ColdBent;
            return PanelKind.Custom;
        }

        public static string Label(PanelKind kind)
        {
            switch (kind)
            {
                case PanelKind.Flat: return "flat";
                case PanelKind.ColdBent: return "cold-bent";
                default: return "custom";
            }
        }
    }
}

