        {
        }

        public override Guid ComponentGuid => new Guid("1a2b3c4d-5e6f-4a7b-8c9d-0e1f2a3b4c04");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new FacadePanelParam(), "Panels", "P", "Panels to classify", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Deviation up to this is flat; up to 10x this is cold-bent", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "Ty", "flat, cold-bent or custom, per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Number of flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "CB", "Number of cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "C", "Number of custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            List<FacadePanel> panels = PanelInput.ReadList(DA, 0);
            double tolerance = 0.5;
            DA.GetData(1, ref tolerance);

            var types = new List<string>(panels.Count);
            int flat = 0, coldBent = 0, custom = 0;

            foreach (FacadePanel panel in panels)
            {
                PanelKind kind = PanelClassifier.Classify(panel.Deviation, tolerance);
                types.Add(PanelClassifier.Label(kind));
                switch (kind)
                {
                    case PanelKind.Flat: flat++; break;
                    case PanelKind.ColdBent: coldBent++; break;
                    default: custom++; break;
                }
            }

            DA.SetDataList(0, types);
            DA.SetData(1, flat);
            DA.SetData(2, coldBent);
            DA.SetData(3, custom);
        }
    }
}

