namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Groups panels whose sorted edge and diagonal lengths match within a tolerance", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("1a2b3c4d-5e6f-4a7b-8c9d-0e1f2a3b4c06");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new FacadePanelParam(), "Panels", "P", "Panels to group", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Largest allowed difference in any edge or diagonal length", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, from 0 in order of first appearance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of distinct groups", GH_ParamAccess.item);
            pManager.AddParameter(new FacadePanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            List<FacadePanel> panels = PanelInput.ReadList(DA, 0);
            double tolerance = 1.0;
            DA.GetData(1, ref tolerance);

            var groupOf = new List<int>(panels.Count);
            var representatives = new List<FacadePanel>();
            var representativeSignatures = new List<double[]>();

            foreach (FacadePanel panel in panels)
            {
                int group = -1;
                for (int g = 0; g < representatives.Count && group < 0; g++)
                {
                    if (SameSignature(panel.Signature, representativeSignatures[g], tolerance))
                        group = g;
                }

                if (group < 0)
                {
                    group = representatives.Count;
                    representatives.Add(panel);
                    representativeSignatures.Add(panel.Signature);
                }
                groupOf.Add(group);
            }

            DA.SetDataList(0, groupOf);
            DA.SetData(1, representatives.Count);
            DA.SetDataList(2, representatives.ConvertAll(p => new FacadePanelGoo(p)));
        }

        private static bool SameSignature(double[] a, double[] b, double tolerance)
        {
            for (int k = 0; k < a.Length; k++)
            {
                if (Math.Abs(a[k] - b[k]) > tolerance) return false;
            }
            return true;
        }
    }
}

