using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    /// <summary>A rectangle placed on a sheet. X and Y are its bottom-left corner in sheet coordinates.</summary>
    public sealed class PlacedPart
    {
        public PlacedPart(int index, int sheet, double x, double y, double width, double height)
        {
            Index = index;
            Sheet = sheet;
            X = x;
            Y = y;
            Width = width;
            Height = height;
        }

        public int Index { get; }
        public int Sheet { get; }
        public double X { get; }
        public double Y { get; }
        public double Width { get; }
        public double Height { get; }
    }

    public sealed class NestResult
    {
        public NestResult(IReadOnlyList<PlacedPart> placed, IReadOnlyList<int> unplaced, int sheetCount, double utilization)
        {
            Placed = placed;
            Unplaced = unplaced;
            SheetCount = sheetCount;
            Utilization = utilization;
        }

        /// <summary>Placed rectangles, in input order.</summary>
        public IReadOnlyList<PlacedPart> Placed { get; }

        /// <summary>Input indices of rectangles that fit on no sheet.</summary>
        public IReadOnlyList<int> Unplaced { get; }

        public int SheetCount { get; }

        /// <summary>Placed rectangle area divided by SheetCount times the sheet area.</summary>
        public double Utilization { get; }
    }

    /// <summary>
    /// Shelf nesting. Rectangles are taken tallest first and filled left to right along a shelf. A part
    /// that does not fit the current shelf starts a new shelf above it, and a part that does not fit
    /// that shelf starts a new sheet. A part is turned 90 degrees only when it fits turned at a position
    /// where it does not fit as given. Pure geometry, no Grasshopper dependencies.
    /// </summary>
    public static class ShelfNester
    {
        private const double Eps = 1e-9;

        public static NestResult Nest(
            IReadOnlyList<(double Width, double Height)> parts,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            CancellationToken token,
            Action<int> progress = null)
        {
            int n = parts.Count;
            var order = Enumerable.Range(0, n)
                .OrderByDescending(i => parts[i].Height)
                .ThenBy(i => i)
                .ToList();

            var placed = new PlacedPart[n];
            var unplaced = new List<int>();

            int sheet = -1;          // index of the current sheet; -1 before the first part
            double shelfY = 0;       // bottom of the current shelf
            double shelfHeight = 0;  // height of the current shelf (0 when no shelf is open)
            double cursorX = 0;      // left edge where the next part on the current shelf goes

            double right = sheetWidth - spacing;
            double top = sheetHeight - spacing;

            for (int step = 0; step < order.Count; step++)
            {
                token.ThrowIfCancellationRequested();

                int i = order[step];
                double w = parts[i].Width;
                double h = parts[i].Height;
                double pw, ph;

                // 1. Continue the current shelf.
                if (shelfHeight > 0 &&
                    FirstFit(w, h, (a, b) => cursorX + a <= right + Eps && b <= shelfHeight + Eps, out pw, out ph))
                {
                    placed[i] = new PlacedPart(i, sheet, cursorX, shelfY, pw, ph);
                    cursorX += pw + spacing;
                }
                // 2. Open a new shelf above the current one on the same sheet.
                else if (sheet >= 0 &&
                         FirstFit(w, h, (a, b) => spacing + a <= right + Eps &&
                                                  shelfY + shelfHeight + spacing + b <= top + Eps, out pw, out ph))
                {
                    shelfY = shelfY + shelfHeight + spacing;
                    shelfHeight = ph;
                    placed[i] = new PlacedPart(i, sheet, spacing, shelfY, pw, ph);
                    cursorX = spacing + pw + spacing;
                }
                // 3. Open a new sheet.
                else if (FirstFit(w, h, (a, b) => spacing + a <= right + Eps && spacing + b <= top + Eps, out pw, out ph))
                {
                    sheet++;
                    shelfY = spacing;
                    shelfHeight = ph;
                    placed[i] = new PlacedPart(i, sheet, spacing, shelfY, pw, ph);
                    cursorX = spacing + pw + spacing;
                }
                else
                {
                    unplaced.Add(i);
                }

                progress?.Invoke((step + 1) * 100 / order.Count);
            }

            var placedList = placed.Where(p => p != null).ToList();
            int sheetCount = sheet + 1;
            double placedArea = placedList.Sum(p => p.Width * p.Height);
            double sheetArea = sheetWidth * sheetHeight;
            double utilization = sheetCount > 0 && sheetArea > 0 ? placedArea / (sheetCount * sheetArea) : 0.0;

            return new NestResult(placedList, unplaced, sheetCount, utilization);
        }

        /// <summary>Returns the first orientation (as given, then turned) that the predicate accepts.</summary>
        private static bool FirstFit(double w, double h, Func<double, double, bool> accept, out double pw, out double ph)
        {
            if (accept(w, h))
            {
                pw = w;
                ph = h;
                return true;
            }
            if (accept(h, w))
            {
                pw = h;
                ph = w;
                return true;
            }
            pw = 0;
            ph = 0;
            return false;
        }
    }
}

