using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One background nesting job. A run is identified by its key (sheet size, spacing and rectangle sizes).
    /// When the key changes, the component cancels the run and starts a new one.
    /// </summary>
    internal sealed class NestingRun
    {
        private long _lastReportTick;

        public NestingRun(double sheetWidth, double sheetHeight, double spacing, IReadOnlyList<(double Width, double Height)> parts)
        {
            SheetWidth = sheetWidth;
            SheetHeight = sheetHeight;
            Spacing = spacing;
            Parts = parts;
            Key = BuildKey(sheetWidth, sheetHeight, spacing, parts);
        }

        public double SheetWidth { get; }
        public double SheetHeight { get; }
        public double Spacing { get; }
        public IReadOnlyList<(double Width, double Height)> Parts { get; }
        public double[] Key { get; }

        public CancellationTokenSource Cancellation { get; } = new CancellationTokenSource();

        public volatile NestResult Result;
        public volatile string Error;
        public volatile int Progress;

        public bool KeyMatches(double[] key) => Key.SequenceEqual(key);

        public void Cancel() => Cancellation.Cancel();

        /// <summary>Throttles progress reports to about five per second.</summary>
        public bool ShouldReportProgress()
        {
            long now = Environment.TickCount64;
            if (now - _lastReportTick < 200) return false;
            _lastReportTick = now;
            return true;
        }

        public static double[] BuildKey(double sheetWidth, double sheetHeight, double spacing, IReadOnlyList<(double Width, double Height)> parts)
        {
            var key = new double[3 + 2 * parts.Count];
            key[0] = sheetWidth;
            key[1] = sheetHeight;
            key[2] = spacing;
            for (int i = 0; i < parts.Count; i++)
            {
                key[3 + 2 * i] = parts[i].Width;
                key[4 + 2 * i] = parts[i].Height;
            }
            return key;
        }
    }
}

