        public CutListComponent()
            : base("Cut List", "CutList", "Builds a CSV cut list for the panels and optionally writes it to a file", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("1a2b3c4d-5e6f-4a7b-8c9d-0e1f2a3b4c08");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new FacadePanelParam(), "Panels", "P", "Panels to list", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "Pa", "File to write the CSV to", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path when true", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Header line, then one line per panel: index, width, height, area, deviation", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "OK", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            List<FacadePanel> panels = PanelInput.ReadList(DA, 0);
            string path = null;
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            string csv = BuildCsv(panels);
            bool written = false;

            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty. Nothing was written.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv, Encoding.UTF8);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write the CSV: " + ex.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }

        private static string BuildCsv(IEnumerable<FacadePanel> panels)
        {
            var sb = new StringBuilder();
            sb.Append("index,width,height,area,deviation\n");
            foreach (FacadePanel p in panels)
            {
                sb.Append(p.Index.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(Format(p.RectWidth)).Append(',')
                  .Append(Format(p.RectHeight)).Append(',')
                  .Append(Format(p.Area)).Append(',')
                  .Append(Format(p.Deviation)).Append('\n');
            }
            return sb.ToString();
        }

        private static string Format(double value) => value.ToString("0.###", CultureInfo.InvariantCulture);
    }
}

