    {
        /// <summary>Gap between neighbouring sheets in the Outlines output.</summary>
        private const double SheetGap = 100.0;

        private NestingRun _run;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nests panel rectangles onto sheets with a shelf algorithm. Runs in the background.", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("1a2b3c4d-5e6f-4a7b-8c9d-0e1f2a3b4c07");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new FacadePanelParam(), "Panels", "P", "Panels to nest", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts, and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Rectangle of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel, in the order of Outlines", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area / (Sheet Count x sheet area)", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            List<FacadePanel> panels = PanelInput.ReadList(DA, 0);
            double sheetWidth = 3000.0, sheetHeight = 1500.0, spacing = 10.0;
            DA.GetData(1, ref sheetWidth);
            DA.GetData(2, ref sheetHeight);
            DA.GetData(3, ref spacing);

            if (sheetWidth <= 0 || sheetHeight <= 0 || spacing < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet Width and Sheet Height must be positive, and Spacing must not be negative.");
                return;
            }

            var parts = panels.Select(p => (Width: p.RectWidth, Height: p.RectHeight)).ToList();
            double[] key = NestingRun.BuildKey(sheetWidth, sheetHeight, spacing, parts);

            // Inputs changed: stop the old run and start a new one.
            if (_run == null || !_run.KeyMatches(key))
            {
                _run?.Cancel();
                _run = new NestingRun(sheetWidth, sheetHeight, spacing, parts);
                StartRun(_run);
            }

            if (_run.Error != null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Nesting failed: " + _run.Error);
                return;
            }

            NestResult result = _run.Result;
            if (result == null)
            {
                // Still running. Outputs stay empty until the run finishes and expires this solution.
                Message = $"Nesting {_run.Progress}%";
                return;
            }

            Message = $"{result.SheetCount} sheet(s)";

            if (result.Unplaced.Count > 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{result.Unplaced.Count} of {parts.Count} panels fit on no sheet and were left out.");
            }

            var outlines = new List<Curve>(result.Placed.Count);
            var sheets = new List<int>(result.Placed.Count);
            foreach (PlacedPart part in result.Placed)
            {
                double ox = part.Sheet * (_run.SheetWidth + SheetGap) + part.X;
                double oy = part.Y;
                var p0 = new Point3d(ox, oy, 0);
                var p1 = new Point3d(ox + part.Width, oy, 0);
                var p2 = new Point3d(ox + part.Width, oy + part.Height, 0);
                var p3 = new Point3d(ox, oy + part.Height, 0);
                outlines.Add(new PolylineCurve(new[] { p0, p1, p2, p3, p0 }));
                sheets.Add(part.Sheet);
            }

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, result.SheetCount);
            DA.SetData(3, result.Utilization);
        }

        private void StartRun(NestingRun run)
        {
            Task.Run(() =>
            {
                try
                {
                    run.Result = ShelfNester.Nest(
                        run.Parts,
                        run.SheetWidth,
                        run.SheetHeight,
                        run.Spacing,
                        run.Cancellation.Token,
                        percent =>
                        {
                            run.Progress = percent;
                            if (run.ShouldReportProgress())
                                PostToCanvas(() => ShowProgress(run));
                        });
                }
                catch (OperationCanceledException)
                {
                    return; // inputs changed; a newer run owns the component now
                }
                catch (Exception ex)
                {
                    run.Error = ex.Message;
                }

                PostToCanvas(() => ExpireSolution(true));
            });
        }

        private void ShowProgress(NestingRun run)
        {
            if (!ReferenceEquals(run, _run) || run.Result != null) return;
            Message = $"Nesting {run.Progress}%";
            OnDisplayExpired(false);
        }

        /// <summary>Runs an action on the Rhino/Grasshopper UI thread.</summary>
        private static void PostToCanvas(Action action)
        {
            RhinoApp.InvokeOnUiThread(action);
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _run?.Cancel();
            _run = null;
            base.RemovedFromDocument(document);
        }
    }
}
